rss.channel:

{{ include.title }}
{{ include.description }}
{{ include.link }}
{% for post in include.posts %}


		{{ post.title | xml_escape }}
		{{ post.abstract | xml_escape }}
		{{ post.date | date_to_rfc822 }}
		{{ post.url | prepend: site.url }}
		{{ post.url | prepend: site.url }}
		{% if post.thumbnail != undefined %}
		{% assign thumbnail_extension = post.thumbnail | split: '.' | last | downcase %}
		{% case thumbnail_extension %}
			{% when 'png' %}{% assign thumbnail_type = 'image/png' %}
			{% when 'gif' %}{% assign thumbnail_type = 'image/gif' %}
			{% when 'webp' %}{% assign thumbnail_type = 'image/webp' %}
			{% when 'svg' %}{% assign thumbnail_type = 'image/svg+xml' %}
			{% else %}{% assign thumbnail_type = 'image/jpeg' %}
		{% endcase %}

		{% endif %}

{% endfor %}
